-- Run once in the Supabase SQL Editor. All app tables use user-scoped RLS.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,language text not null default 'en');
create table if not exists public.platforms(id uuid primary key default gen_random_uuid(),name text unique not null);
insert into public.platforms(name) values('Instagram'),('LinkedIn'),('TikTok'),('YouTube'),('YouTube Shorts') on conflict do nothing;
create table if not exists public.clients(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,industry text,description text,website text,contacts text,links text,notes text,archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.client_platforms(client_id uuid not null references public.clients(id) on delete cascade,platform_id uuid not null references public.platforms(id),primary key(client_id,platform_id));
create table if not exists public.brand_guidelines(id uuid primary key default gen_random_uuid(),client_id uuid not null unique references public.clients(id) on delete cascade,positioning text default '',value_proposition text default '',audience text default '',personality text default '',tone text default '',preferred_words text default '',avoided_words text default '',visual_identity text default '',colors text default '',fonts text default '',logos text default '',restrictions text default '');
create table if not exists public.platform_strategies(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete cascade,platform_id uuid not null references public.platforms(id),objectives text default '',audience text default '',positioning text default '',tone text default '',content_pillars text default '',formats text default '',frequency text default '',opportunities text default '',competitors text default '',best_practices text default '',dos text default '',donts text default '',notes text default '',unique(client_id,platform_id));
create table if not exists public.knowledge_items(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete cascade,title text not null,category text,kind text not null default 'text',content text,file_path text,created_at timestamptz not null default now());
create table if not exists public.feedback_entries(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete cascade,entry_type text,entry_date date default current_date,content text not null,created_at timestamptz not null default now());
create table if not exists public.dashboard_layouts(user_id uuid primary key references auth.users(id) on delete cascade,layout jsonb not null default '[]'::jsonb);
create or replace function public.owns_client(cid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.clients where id=cid and user_id=(select auth.uid()))$$;
create or replace function public.touch_client() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
drop trigger if exists clients_touch on public.clients;
create trigger clients_touch before update on public.clients for each row execute function public.touch_client();
alter table public.profiles enable row level security;alter table public.platforms enable row level security;alter table public.clients enable row level security;alter table public.client_platforms enable row level security;alter table public.brand_guidelines enable row level security;alter table public.platform_strategies enable row level security;alter table public.knowledge_items enable row level security;alter table public.feedback_entries enable row level security;alter table public.dashboard_layouts enable row level security;
create policy "profile owner" on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "read platforms" on public.platforms for select to authenticated using(true);
create policy "clients read" on public.clients for select to authenticated using(user_id=(select auth.uid()));
create policy "clients insert" on public.clients for insert to authenticated with check(user_id=(select auth.uid()));
create policy "clients update" on public.clients for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "client platform access" on public.client_platforms for all to authenticated using(public.owns_client(client_id)) with check(public.owns_client(client_id));
create policy "guideline access" on public.brand_guidelines for all to authenticated using(public.owns_client(client_id)) with check(public.owns_client(client_id));
create policy "strategy access" on public.platform_strategies for all to authenticated using(public.owns_client(client_id)) with check(public.owns_client(client_id));
create policy "knowledge access" on public.knowledge_items for all to authenticated using(public.owns_client(client_id)) with check(public.owns_client(client_id));
create policy "feedback access" on public.feedback_entries for all to authenticated using(public.owns_client(client_id)) with check(public.owns_client(client_id));
create policy "layout access" on public.dashboard_layouts for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
revoke delete on public.clients from authenticated;
insert into storage.buckets(id,name,public,file_size_limit) values('client-documents','client-documents',false,26214400) on conflict(id) do nothing;
create policy "private uploads" on storage.objects for insert to authenticated with check(bucket_id='client-documents' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "private downloads" on storage.objects for select to authenticated using(bucket_id='client-documents' and (storage.foldername(name))[1]=(select auth.uid())::text);
